// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, uint8 seed) public {
        vm.assume(amount >= 1 && amount <= 1 ether);
        address user = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(user != address(0) && user != address(this) && user != address(c));

        vm.deal(user, amount);
        vm.prank(user);
        c.addToBalance{value: amount}();

        bool firstOk;
        uint256 balBeforeFirst = user.balance;
        vm.prank(user);
        try c.withdrawBalance() { firstOk = true; } catch { firstOk = false; }
        uint256 balAfterFirst = user.balance;
        require(firstOk, "First withdrawal should succeed");

        vm.deal(user, amount);
        vm.prank(user);
        c.addToBalance{value: amount}();

        bool secondOk;
        uint256 balBeforeSecond = user.balance;
        vm.prank(user);
        try c.withdrawBalance() { secondOk = true; } catch { secondOk = false; }
        uint256 balAfterSecond = user.balance;

        assertTrue(
            (secondOk && balAfterSecond == balBeforeSecond + amount) ||
            (!secondOk && balAfterSecond == balBeforeSecond)
        );
    }
}
